using EFootwear.BLL.Contacts.Contracts;

namespace EFootwear.BLL.Vendors.Contracts;

/// <summary>
/// New Vendor. The name and the phone number are required; the email, the birth date and the city are optional. The code is generated by
/// the server. The credit limit (whole rupees) is optional: no limit when it is missing.
/// </summary>
public sealed record CreateVendorRequest(
    string Name,
    string? Phone,
    string? Email,
    DateOnly? BirthDate,
    Guid? CityId,
    long? CreditLimit,
    string StatusCode,
    ContactOpeningBalanceRequest? OpeningBalance) : IVendorEditableFields;
